SINGLE_BIT_RESULT_OPS = frozenset(
    {"comb.icmp", "comb.parity", "arith.cmpi", "arith.cmpf", "seq.from_clock"}
)

#: Operations whose result width is the sum of the operand widths.
SUMMED_WIDTH_OPS = frozenset({"comb.concat"})

#: Operations that forward the type of a specific operand.
_FORWARDED_OPERAND = {
    "comb.mux": 1,
    "hw.wire": 0,
    "seq.compreg": 0,
    "seq.compreg.ce": 0,
    "seq.firreg": 0,
    "firrtl.node": 0,
