class TypeResolver:
    """Derives a type and a :class:`Sort` for every value in an operation tree."""

    #: Safety net for the fixed-point loop.
    MAX_ITERATIONS = 8

    def __init__(
        self,
        root: Operation,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        self.symbols = symbols if symbols is not None else SymbolResolver(root).resolve()
        self._resolution: Optional[TypeResolution] = None

    # -- entry point ------------------------------------------------------
    def resolve(self) -> TypeResolution:
        """Run the analysis (cached: repeated calls return the same result)."""
        if self._resolution is not None:
            return self._resolution

        resolution = TypeResolution()
        self._collect_signatures(resolution)
        self._seed_declared_types(resolution)

        for iteration in range(1, self.MAX_ITERATIONS + 1):
            resolution.iterations = iteration
            if not self._infer_once(resolution):
                break

        self._resolution = resolution
        return resolution

    # -- signatures -------------------------------------------------------
    def _collect_signatures(self, resolution: TypeResolution) -> None:
        for name, entry in self.symbols.definitions.items():
            op = entry.op
            if op is None:
                continue
            attr = op.attributes.get("function_type")
            if isinstance(attr, TypeAttr) and isinstance(attr.value, FunctionType):
                resolution.signatures[name] = attr.value

    # -- declared types ---------------------------------------------------
    def _seed_declared_types(self, resolution: TypeResolution) -> None:
        env = resolution.environment

        def visit(op: Operation) -> None:
            scope = self._scope_name(op)
            for region in op.regions:
                for block in region.blocks:
                    for index, argument in enumerate(block.arguments):
                        name = argument.name or f"arg{index}"
                        self._bind(env, scope, name, argument.type, argument, op, False)
            for result in op.results:
                if not result.name:
                    continue
                self._bind(env, scope, result.name, result.type, result, op, False)

        self.root.walk(visit)

    def _scope_name(self, op: Operation) -> str:
        """The name of the symbol-carrying ancestor (or the op itself)."""
        from mlir.ir import SymbolTable

        current: Optional[Operation] = op
        while current is not None:
            symbol = SymbolTable.get_symbol_name(current)
            if symbol is not None and current.name != "builtin.module":
                return symbol
            current = current.parent_op
        return self.symbols.root_scope.name

    def _bind(
        self,
        env: TypeEnvironment,
        scope: str,
        name: str,
        type: Optional[Type],
        value: Optional[Value],
        op: Optional[Operation],
        inferred: bool,
    ) -> TypeBinding:
        key = f"{scope}::{name}" if scope else name
        binding = TypeBinding(
            key=key,
            type=type,
            sort=sort_of(type),
            width=width_of(type),
            value=value,
            op=op,
            inferred=inferred,
        )
        return env.bind(binding)

    # -- inference --------------------------------------------------------
    def _infer_once(self, resolution: TypeResolution) -> bool:
        """One inference sweep.  Returns ``True`` when something changed."""
        env = resolution.environment
        changed = False

        def visit(op: Operation) -> None:
            nonlocal changed
            for result in op.results:
                binding = env.lookup_value(result)
                if binding is not None and binding.is_resolved:
                    continue
                inferred = self.infer_result_type(op, result, env)
                if inferred is None:
                    continue
                scope = self._scope_name(op)
                name = result.name or f"{op.mnemonic}{result.index}"
                previous = binding.type if binding is not None else None
                if previous is not None and previous != inferred:
                    resolution.conflicts.append(
                        TypeConflict(name, previous, inferred, op)
                    )
                    continue
                self._bind(env, scope, name, inferred, result, op, True)
                # Fill the gap in the IR too, but never overwrite a type the
                # source actually spelled out.
                if result.type is None:
                    result.type = inferred
                changed = True

        self.root.walk(visit)
        return changed

    def infer_result_type(
        self,
        op: Operation,
        result: OpResult,
        env: Optional[TypeEnvironment] = None,
    ) -> Optional[Type]:
        """Infer the type of ``result`` from ``op``'s operands and attributes."""
        env = env if env is not None else TypeEnvironment()

        if op.name in SINGLE_BIT_RESULT_OPS:
            return IntegerType(1)

        value_attr = op.attributes.get("value")
        declared = getattr(value_attr, "type", None)
        if declared is not None:
            return declared

        operand_types = [self._operand_type(operand, env) for operand in op.operands]
        known = [t for t in operand_types if t is not None]

        if op.name in SUMMED_WIDTH_OPS:
            widths = [width_of(t) for t in known]
            if widths and all(widths):
                return IntegerType(sum(widths))
            return None

        index = _FORWARDED_OPERAND.get(op.name)
        if index is not None and index < len(operand_types):
            return operand_types[index]

        # The general rule: same-typed operands give a same-typed result, which
        # covers every ``comb``/``arith`` binary operation.
        for candidate in known:
            if sort_of(candidate) in (Sort.INT, Sort.BOOL):
                return candidate
        return known[0] if known else None

