@dataclass
class TypeResolution:
    """The result of running :class:`TypeResolver`."""

    environment: TypeEnvironment = field(default_factory=TypeEnvironment)
    conflicts: List[TypeConflict] = field(default_factory=list)
    signatures: Dict[str, FunctionType] = field(default_factory=dict)
    iterations: int = 0

    # -- counts -----------------------------------------------------------
    @property
    def num_typed(self) -> int:
        return sum(1 for b in self.environment.bindings if b.is_resolved)

    @property
    def num_inferred(self) -> int:
        return sum(1 for b in self.environment.bindings if b.inferred and b.is_resolved)

    @property
    def unresolved(self) -> List[TypeBinding]:
        return [b for b in self.environment.bindings if not b.is_resolved]

    @property
    def is_consistent(self) -> bool:
        return not self.conflicts

    @property
    def is_complete(self) -> bool:
        return not self.conflicts and not self.unresolved

    # -- lookup -----------------------------------------------------------
    def type_of(self, key: Any) -> Optional[Type]:
        return self.environment.type_of(key)

    def sort_of(self, key: Any) -> Sort:
        return self.environment.sort(key)

